// Exact binomial machinery in log space, stable for n in the thousands. Ported from the failure calculus
// so a client statistician can audit it in one file.

const logFactCache: number[] = [0, 0]
function logFact(n: number): number {
  for (let i = logFactCache.length; i <= n; i++) logFactCache[i] = (logFactCache[i - 1] ?? 0) + Math.log(i)
  return logFactCache[n] ?? 0
}
const logChoose = (n: number, k: number) => logFact(n) - logFact(k) - logFact(n - k)

function binomPmf(k: number, n: number, p: number): number {
  if (p <= 0) return k === 0 ? 1 : 0
  if (p >= 1) return k === n ? 1 : 0
  return Math.exp(logChoose(n, k) + k * Math.log(p) + (n - k) * Math.log(1 - p))
}
function binomCdf(k: number, n: number, p: number): number {
  let s = 0
  for (let i = 0; i <= k; i++) s += binomPmf(i, n, p)
  return Math.min(1, s)
}
const binomTailGE = (k: number, n: number, p: number) => (k <= 0 ? 1 : 1 - binomCdf(k - 1, n, p))

export type Interval = { lower: number; upper: number }

/** Clopper-Pearson exact interval for passes out of n, found by bisection on the binomial CDF. */
export function clopperPearson(passes: number, n: number, confidence = 0.95): Interval {
  if (!Number.isInteger(n) || n < 1) throw new RangeError('n must be a positive integer')
  if (!Number.isInteger(passes) || passes < 0 || passes > n) throw new RangeError('passes must be an integer from 0 to n')
  const alpha = 1 - confidence
  const bisect = (isLow: (p: number) => boolean) => {
    let lo = 0
    let hi = 1
    for (let i = 0; i < 100; i++) {
      const mid = (lo + hi) / 2
      if (isLow(mid)) lo = mid
      else hi = mid
    }
    return (lo + hi) / 2
  }
  const lower = passes === 0 ? 0 : bisect((p) => binomTailGE(passes, n, p) <= alpha / 2)
  const upper = passes === n ? 1 : bisect((p) => binomCdf(passes, n, p) > alpha / 2)
  return { lower, upper }
}

/** Upper bound on the true failure rate when zero failures were seen in n cases: 1 - alpha^(1/n). */
export function zeroFailureUpperBound(n: number, confidence = 0.95): number {
  if (!Number.isInteger(n) || n < 1) throw new RangeError('n must be a positive integer')
  return 1 - Math.pow(1 - confidence, 1 / n)
}

/**
 * Exact McNemar p-value (two-sided) for a paired re-test on the same case set. Under no change, the cases
 * that flipped split Binomial(regressed + improved, 0.5).
 */
export function mcnemarExact(regressed: number, improved: number): number {
  if (![regressed, improved].every((x) => Number.isInteger(x) && x >= 0)) throw new RangeError('counts must be non-negative integers')
  const n = regressed + improved
  if (n === 0) return 1
  return Math.min(1, 2 * binomCdf(Math.min(regressed, improved), n, 0.5))
}

/* klyra: plain CSS, no Tailwind. Theme by overriding the --kl-* variables, or inherit a shadcn theme:
   --background, --foreground, --muted-foreground, --border and --primary are read when present. */
.kl {
  --kl-bg: var(--background, #ffffff);
  --kl-fg: var(--foreground, #16181d);
  --kl-muted: var(--muted-foreground, #5d6470);
  --kl-line: var(--border, #e3e5ea);
  --kl-accent: var(--primary, #1d232b);
  --kl-surface: color-mix(in srgb, var(--kl-fg) 4%, var(--kl-bg));
  --kl-good: #1b7249;
  --kl-warn: #8f4f00;
  --kl-bad: #b3261e;
  --kl-radius: 10px;
  --kl-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--kl-fg);
  background: var(--kl-bg);
  border: 1px solid var(--kl-line);
  border-radius: var(--kl-radius);
  padding: 16px;
  font: 14px/1.45 system-ui, -apple-system, 'Segoe UI', sans-serif;
  box-sizing: border-box;
}
/* Dark theme: follows the OS unless data-theme says otherwise. The host's shadcn variables win when present;
   the fallbacks keep every pair readable when the host defines none. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) .kl { --kl-bg: var(--background, #0e1115); --kl-fg: var(--foreground, #ececec); --kl-muted: var(--muted-foreground, #9aa1ab); --kl-line: var(--border, #2a3038); --kl-accent: var(--primary, #e7b65c); --kl-good: #5fcf94; --kl-warn: #f0a85a; --kl-bad: #ff8a80; --kl-c1: #6ea0ff; --kl-c2: #f0a85a; --kl-c3: #5fcf94; --kl-c4: #b896f0; --kl-c5: #f27f9a; --kl-c6: #5ccbdc; --kl-c7: #d8c35a; --kl-c8: #9aa1ab; --kl-on-c: #0e1115; }
}
:root[data-theme='dark'] .kl { --kl-bg: var(--background, #0e1115); --kl-fg: var(--foreground, #ececec); --kl-muted: var(--muted-foreground, #9aa1ab); --kl-line: var(--border, #2a3038); --kl-accent: var(--primary, #e7b65c); --kl-good: #5fcf94; --kl-warn: #f0a85a; --kl-bad: #ff8a80; --kl-c1: #6ea0ff; --kl-c2: #f0a85a; --kl-c3: #5fcf94; --kl-c4: #b896f0; --kl-c5: #f27f9a; --kl-c6: #5ccbdc; --kl-c7: #d8c35a; --kl-c8: #9aa1ab; --kl-on-c: #0e1115; }
.kl *, .kl *::before, .kl *::after { box-sizing: border-box; }
.kl-title { margin: 0 0 12px; font-size: 15px; font-weight: 600; }
.kl-sub { color: var(--kl-muted); font-size: 12px; }
.kl-mono { font-variant-numeric: tabular-nums; }
.kl-id { font-family: var(--kl-mono); font-size: 0.92em; }
.kl-list { list-style: none; margin: 0; padding: 0; }
.kl-pill { display: inline-flex; align-items: center; gap: 4px; padding: 1px 9px; border-radius: 999px; font-size: 12.5px; font-weight: 500; background: var(--kl-surface); color: var(--kl-muted); white-space: nowrap; }
.kl-pill[data-tone='good'] { color: var(--kl-good); background: color-mix(in srgb, var(--kl-good) 13%, var(--kl-bg)); }
.kl-pill[data-tone='warn'] { color: var(--kl-warn); background: color-mix(in srgb, var(--kl-warn) 14%, var(--kl-bg)); }
.kl-pill[data-tone='bad'] { color: var(--kl-bad); background: color-mix(in srgb, var(--kl-bad) 12%, var(--kl-bg)); }

/* Swimlane */
.kl-lane { display: grid; grid-template-columns: 110px 1fr; gap: 12px; padding: 8px 0; border-top: 1px solid var(--kl-line); }
.kl-lane:first-of-type { border-top: 0; }
.kl-lane-owner { font-weight: 600; font-size: 13px; }
.kl-steps { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.kl-step { padding: 4px 10px; border-radius: 6px; border: 1px solid var(--kl-line); background: var(--kl-surface); }
.kl-step[data-waiting='true'] { border-color: var(--kl-warn); color: var(--kl-warn); }
.kl-arrow { color: var(--kl-muted); }

/* Trail */
.kl-stop { position: relative; display: grid; grid-template-columns: 20px 1fr auto; gap: 10px; padding-bottom: 14px; }
.kl-stop::before { content: ''; position: absolute; left: 4px; top: 14px; bottom: 0; width: 1px; background: var(--kl-line); }
.kl-stop:last-child::before { display: none; }
.kl-dot { width: 9px; height: 9px; margin-top: 5px; border-radius: 50%; background: var(--kl-accent); }
.kl-dot[data-wait='true'] { background: var(--kl-warn); }

/* Bars (Bottlenecks, Funnel) */
.kl-row { display: grid; grid-template-columns: minmax(80px, 160px) 1fr auto; gap: 10px; align-items: center; padding: 4px 0; }
.kl-bar { height: 10px; border-radius: 5px; background: var(--kl-surface); overflow: hidden; }
.kl-bar > span { display: block; height: 100%; background: var(--kl-accent); border-radius: 5px; }
.kl-bar > span[data-top='true'] { background: var(--kl-warn); }
.kl-kept { margin: 0 0 0 4px; font-size: 12px; color: var(--kl-muted); }

/* Priority */
.kl-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.kl-cell { border: 1px solid var(--kl-line); border-radius: 8px; padding: 10px; min-height: 84px; background: var(--kl-surface); }
.kl-cell h4 { margin: 0 0 6px; font-size: 12.5px; font-weight: 500; color: var(--kl-muted); }
.kl-cell ul { margin: 0; padding-left: 16px; }

/* Compare */
.kl-compare { display: grid; grid-template-columns: 120px 1fr 1fr; gap: 0; border: 1px solid var(--kl-line); border-radius: 8px; overflow: hidden; }
.kl-compare > div { padding: 8px 10px; border-top: 1px solid var(--kl-line); }
.kl-compare > .kl-head { border-top: 0; background: var(--kl-surface); font-weight: 600; font-size: 12px; }
.kl-compare > .kl-label { color: var(--kl-muted); }

/* Records */
.kl-head-row { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start; gap: 12px; margin-bottom: 8px; }
.kl-dl { display: grid; grid-template-columns: max-content 1fr; gap: 4px 12px; margin: 8px 0 0; }
.kl-dl dt { color: var(--kl-muted); }
.kl-dl dd { margin: 0; }
.kl-verdict { display: flex; align-items: center; gap: 10px; font-size: 16px; font-weight: 600; }
.kl-verdict[data-ok='true'] { color: var(--kl-good); }
.kl-verdict[data-ok='false'] { color: var(--kl-bad); }
.kl-verdict[data-ok='unknown'] { color: var(--kl-muted); }
.kl-problems { margin: 8px 0 0; padding-left: 18px; color: var(--kl-bad); }
.kl-event { display: grid; grid-template-columns: 28px 1fr auto; gap: 10px; padding: 8px 0; border-top: 1px solid var(--kl-line); }
.kl-event:first-child { border-top: 0; }
.kl-event[data-flag='bad'] .kl-evtype { color: var(--kl-bad); }
.kl-event[data-flag='warn'] .kl-evtype { color: var(--kl-warn); }
.kl-event[data-flag='good'] .kl-evtype { color: var(--kl-good); }
.kl-evtype { font-weight: 600; }
.kl-track { position: relative; height: 12px; border-radius: 6px; background: var(--kl-surface); border: 1px solid var(--kl-line); margin: 10px 0 6px; }
.kl-band { position: absolute; top: 0; bottom: 0; background: color-mix(in srgb, var(--kl-accent) 30%, transparent); border-radius: 6px; }
.kl-mark { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--kl-fg); }
.kl-mark[data-kind='threshold'] { background: var(--kl-warn); }
.kl-progress { height: 8px; border-radius: 4px; background: var(--kl-surface); overflow: hidden; margin: 8px 0; }
.kl-progress > span { display: block; height: 100%; background: var(--kl-accent); }
.kl-progress[data-state='late'] > span, .kl-progress[data-state='bad'] > span { background: var(--kl-bad); }
.kl-progress[data-state='ok'] > span { background: var(--kl-good); }

/* Controls */
.kl-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.kl-chip, .kl-sortbtn, .kl-twist { font: inherit; color: inherit; background: transparent; border: 1px solid var(--kl-line); border-radius: 999px; padding: 2px 10px; cursor: pointer; }
.kl-chip[aria-pressed='true'] { background: var(--kl-accent); color: var(--kl-bg); border-color: var(--kl-accent); }
.kl-sortbtn { border: 0; padding: 0; font-weight: 600; border-radius: 4px; }
.kl-twist { border: 0; width: 18px; padding: 0; display: inline-block; text-align: center; }
.kl :is(.kl-chip, .kl-sortbtn, .kl-twist, select):focus-visible { outline: 2px solid var(--kl-accent); outline-offset: 2px; }
.kl select { font: inherit; color: inherit; background: var(--kl-bg); border: 1px solid var(--kl-line); border-radius: 6px; padding: 2px 6px; margin-left: 4px; }
.kl-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; padding: 0; }
.kl-scroll { overflow-x: auto; }

/* Table */
.kl-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.kl-table th, .kl-table td { text-align: left; padding: 6px 10px; border-top: 1px solid var(--kl-line); vertical-align: top; }
.kl-table thead th { border-top: 0; font-size: 12px; color: var(--kl-muted); }
.kl-table tbody th { font-weight: 500; }
.kl-table tfoot th, .kl-table tfoot td { border-top: 2px solid var(--kl-line); }
.kl-table td[data-pass='true'] { color: var(--kl-good); }
.kl-table td[data-pass='false'] { color: var(--kl-bad); background: color-mix(in srgb, var(--kl-bad) 8%, transparent); }
.kl-table tr[data-flip='regressed'] > th { box-shadow: inset 3px 0 var(--kl-bad); }
.kl-table tr[data-flip='improved'] > th { box-shadow: inset 3px 0 var(--kl-good); }
.kl-compare-bar { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin: 12px 0 8px; }

/* AgentTrace */

/* EvidenceDiff */
.kl [data-kind='add'] { background: color-mix(in srgb, var(--kl-good) 14%, transparent); }
.kl [data-kind='del'] { background: color-mix(in srgb, var(--kl-bad) 14%, transparent); }
.kl-word { color: inherit; border-radius: 2px; }
.kl-word[data-kind='add'] { background: color-mix(in srgb, var(--kl-good) 38%, transparent); }
.kl-word[data-kind='del'] { background: color-mix(in srgb, var(--kl-bad) 38%, transparent); }

/* ApprovalFlow */
.kl-flow-edge { fill: none; stroke: var(--kl-muted); stroke-width: 1.5; }
.kl-flow-arrow { fill: var(--kl-muted); }
.kl-flow-label { fill: var(--kl-muted); font: 11px system-ui, sans-serif; paint-order: stroke; stroke: var(--kl-bg); stroke-width: 4px; stroke-linejoin: round; }

/* ChainGraph */
.kl-chain { display: flex; align-items: stretch; padding: 4px 0 8px; }
.kl-block { flex: 0 0 204px; border: 1px solid var(--kl-line); border-radius: 8px; padding: 8px 10px; display: grid; gap: 2px; align-content: start; background: var(--kl-surface); }
.kl-block .kl-pill { white-space: nowrap; justify-self: start; margin-top: 4px; }
.kl-block[data-bad='true'] { border-color: var(--kl-bad); }
.kl-link { flex: 0 0 32px; align-self: center; height: 2px; background: var(--kl-good); position: relative; }
.kl-link[data-ok='false'] { background: repeating-linear-gradient(90deg, var(--kl-bad) 0 4px, transparent 4px 8px); }
.kl-link > span { position: absolute; top: -18px; left: 50%; transform: translateX(-50%); color: var(--kl-bad); font-weight: 700; }

/* Receipt */
.kl-receipt-foot { margin-top: 12px; padding-top: 10px; border-top: 1px dashed var(--kl-line); display: grid; gap: 8px; }
@media print { .kl { border-color: #999; break-inside: avoid; } }

/* Categorical palette, used by anything that colours by kind */
.kl { --kl-c1: #2563c7; --kl-c2: #a85a0a; --kl-c3: #1d7a56; --kl-c4: #7a4cc2; --kl-c5: #bf3557; --kl-c6: #17788a; --kl-c7: #7d6a0f; --kl-c8: #5b6470; --kl-on-c: #ffffff; font-variant-numeric: tabular-nums; }
.kl-num { text-align: right !important; }
.kl-ell { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.kl-dot-kind { display: inline-block; width: 9px; height: 9px; border-radius: 2px; flex: none; }
.kl-linkbtn { font: inherit; color: var(--kl-accent); background: none; border: 0; padding: 0; cursor: pointer; text-decoration: underline; text-underline-offset: 2px; }
.kl-input { font: inherit; color: inherit; background: var(--kl-bg); border: 1px solid var(--kl-line); border-radius: 8px; padding: 4px 10px; min-width: 160px; }
.kl-input:focus-visible, .kl-trace-body:focus-visible { outline: 2px solid var(--kl-accent); outline-offset: 2px; }
.kl-chip:disabled { opacity: 0.45; cursor: default; }
.kl-tabs { display: inline-flex; background: var(--kl-surface); border-radius: 8px; padding: 2px; gap: 2px; }
.kl-tab { font: inherit; font-size: 13px; color: var(--kl-muted); background: transparent; border: 0; border-radius: 6px; padding: 3px 10px; cursor: pointer; }
.kl-tab[aria-selected='true'] { background: var(--kl-bg); color: var(--kl-fg); }
.kl-tab:disabled { opacity: 0.4; cursor: default; }
.kl-tab:focus-visible { outline: 2px solid var(--kl-accent); outline-offset: 1px; }
.kl-facts { display: flex; flex-wrap: wrap; gap: 6px 22px; margin: 4px 0 10px; }
.kl-facts > div { display: grid; }
.kl-facts dt { font-size: 12px; color: var(--kl-muted); }
.kl-facts dd { margin: 0; font-size: 16px; font-weight: 600; }
.kl-facts [data-bad='true'] dd { color: var(--kl-bad); }
.kl-facts [data-warn='true'] dd { color: var(--kl-warn); }
.kl-toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-bottom: 8px; }
.kl-zoom { display: inline-flex; gap: 4px; }
.kl-legend { display: flex; flex-wrap: wrap; gap: 4px 6px; margin-bottom: 10px; }
