.kl-legend-item[aria-pressed='true'] { border-color: var(--kl-accent); background: color-mix(in srgb, var(--kl-accent) 10%, transparent); }
.kl-trace-body { position: relative; border: 1px solid var(--kl-line); border-radius: 10px; background: var(--kl-surface); overflow: hidden; outline-offset: 2px; }
