.kl-gridline { position: absolute; top: 0; bottom: 0; width: 1px; background: color-mix(in srgb, var(--kl-fg) 8%, transparent); pointer-events: none; }
.kl-flame { position: relative; margin: 4px 0; }
.kl-bar-span { position: absolute; border-radius: 3px; color: var(--kl-on-c); font-size: 11.5px; line-height: 19px; padding: 0 5px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; cursor: pointer; }
.kl-bar-span > span { display: block; overflow: hidden; text-overflow: ellipsis; }
