.kl-bar-span[data-dim='true'], .kl-wrow[data-dim='true'] { opacity: 0.22; }
.kl-bar-span[data-status='error'] { background-image: repeating-linear-gradient(135deg, rgb(255 255 255 / 0.28) 0 3px, transparent 3px 7px) !important; outline: 1.5px solid var(--kl-bad); outline-offset: -1.5px; }
.kl-bar-span[data-status='blocked'] { outline: 1.5px dashed var(--kl-warn); outline-offset: -1.5px; }
.kl-bar-span[data-critical='true'] { outline: 2px solid var(--kl-fg); outline-offset: 0; z-index: 1; }
.kl-bar-span[data-selected='true'] { outline: 2px solid var(--kl-accent); outline-offset: 2px; z-index: 2; }
.kl-wfall { padding: 4px 0; max-height: 380px; overflow: auto; }
.kl-wrow { display: grid; grid-template-columns: minmax(150px, 30%) 1fr; align-items: center; min-height: 26px; cursor: pointer; }
.kl-wrow:hover, .kl-wrow[data-selected='true'] { background: color-mix(in srgb, var(--kl-accent) 9%, transparent); }
.kl-wname { display: flex; align-items: center; gap: 6px; padding-right: 8px; min-width: 0; }
.kl-wtrack { position: relative; height: 18px; }
.kl-wbar { position: absolute; top: 3px; height: 12px; border-radius: 3px; }
.kl-wbar[data-status='error'] { outline: 1.5px solid var(--kl-bad); background-image: repeating-linear-gradient(135deg, rgb(255 255 255 / 0.3) 0 3px, transparent 3px 7px) !important; }
.kl-wbar[data-status='blocked'] { outline: 1.5px dashed var(--kl-warn); }
.kl-wbar[data-critical='true'] { outline: 2px solid var(--kl-fg); }
.kl-wlabel { position: absolute; top: 1px; font-size: 11px; color: var(--kl-muted); white-space: nowrap; }
.kl-list-table tbody tr { cursor: pointer; }
.kl-list-table tbody tr:hover, .kl-list-table tbody tr[data-selected='true'] { background: color-mix(in srgb, var(--kl-accent) 9%, transparent); }
.kl-share { display: inline-block; width: 90px; height: 7px; border-radius: 4px; background: var(--kl-line); vertical-align: middle; overflow: hidden; }
.kl-share > span { display: block; height: 100%; border-radius: 4px; }
.kl-tip { position: absolute; z-index: 5; pointer-events: none; min-width: 190px; background: var(--kl-bg); color: var(--kl-fg); border: 1px solid var(--kl-line); border-radius: 8px; padding: 8px 10px; box-shadow: 0 6px 20px color-mix(in srgb, var(--kl-fg) 18%, transparent); font-size: 12.5px; }
.kl-detail { margin-top: 12px; border-top: 1px solid var(--kl-line); padding-top: 10px; }
.kl-io { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px; }

/* JsonTree */
.kl-json { font: 12.5px/1.6 var(--kl-mono); background: var(--kl-bg); border: 1px solid var(--kl-line); border-radius: 8px; padding: 6px 8px; overflow: auto; max-height: 260px; }
.kl-json-row { display: flex; align-items: baseline; gap: 2px; white-space: nowrap; }
