.kl-json-key { background: none; border: 0; padding: 0; font: inherit; color: var(--kl-c4); cursor: pointer; }
.kl-json-key:hover { text-decoration: underline; }
.kl-json-colon, .kl-json-punct { color: var(--kl-muted); }
.kl-json-summary { color: var(--kl-muted); font-style: italic; }
.kl-json-copied { color: var(--kl-good); font-size: 11px; }
.kl-json-val[data-kind='string'] { color: var(--kl-c3); white-space: pre-wrap; word-break: break-word; }
.kl-json-val[data-kind='number'] { color: var(--kl-c2); }
.kl-json-val[data-kind='boolean'] { color: var(--kl-c1); }
.kl-json-val[data-kind='null'], .kl-json-val[data-kind='other'] { color: var(--kl-muted); }
.kl-json-more { background: none; border: 0; color: var(--kl-accent); font: inherit; font-size: 11.5px; cursor: pointer; margin-left: 8px; text-decoration: underline; }

/* DiffViewer */
.kl-add { color: var(--kl-good); font-weight: 600; }
.kl-del { color: var(--kl-bad); font-weight: 600; }
.kl-spacer { flex: 1; }
.kl-statbar { display: inline-flex; gap: 2px; vertical-align: middle; margin-left: 4px; }
.kl-statbar i { width: 8px; height: 8px; border-radius: 1px; background: var(--kl-line); }
.kl-statbar i[data-k='add'] { background: var(--kl-good); }
.kl-statbar i[data-k='del'] { background: var(--kl-bad); }
.kl-diffv-body { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 14px; margin-top: 10px; align-items: start; }
.kl-diffv-body:not(:has(.kl-ftree)) { grid-template-columns: minmax(0, 1fr); }
.kl-ftree { display: grid; gap: 2px; width: 230px; align-content: start; position: sticky; top: 8px; font-size: 13px; }
.kl-ftree a { display: flex; justify-content: space-between; gap: 8px; padding: 5px 8px; border-radius: 6px; color: inherit; text-decoration: none; }
.kl-ftree a:hover { background: var(--kl-surface); }
.kl-ftree a:focus-visible { outline: 2px solid var(--kl-accent); }
.kl-fcount { font-size: 12px; white-space: nowrap; flex: none; }
.kl-ftree a > .kl-ell { min-width: 0; flex: 1; }
.kl-c-ln { width: 46px; }
.kl-c-sign { width: 18px; }
.kl-files { display: grid; gap: 12px; min-width: 0; }
.kl-file { border: 1px solid var(--kl-line); border-radius: 8px; overflow: hidden; }
.kl-file-head { display: flex; align-items: center; gap: 8px; padding: 6px 10px; background: var(--kl-surface); font-size: 13px; }
.kl-viewed { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; color: var(--kl-muted); cursor: pointer; }
.kl-dtable { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 12.5px; }
.kl-dtable[data-mode='split'] .kl-ln { width: 42px; }
