.kl-dtable[data-mode='unified'] .kl-ln { width: 46px; }
.kl-dtable[data-mode='unified'] .kl-sign { width: 18px; }
.kl-ln { text-align: right; padding: 0 8px; color: var(--kl-muted); user-select: none; cursor: pointer; font: 12px/1.6 var(--kl-mono); vertical-align: top; background: color-mix(in srgb, var(--kl-fg) 3%, transparent); }
.kl-ln[data-active='true'] { color: var(--kl-fg); background: color-mix(in srgb, var(--kl-warn) 28%, transparent); }
.kl-sign { text-align: center; color: var(--kl-muted); vertical-align: top; font: 12px/1.6 var(--kl-mono); }
.kl-sign[data-kind='add'], .kl-code[data-kind='add'] { background: color-mix(in srgb, var(--kl-good) 14%, transparent); }
.kl-sign[data-kind='del'], .kl-code[data-kind='del'] { background: color-mix(in srgb, var(--kl-bad) 14%, transparent); }
.kl-code { padding: 0 8px; white-space: pre-wrap; word-break: break-word; line-height: 1.6; vertical-align: top; }
.kl-code[data-kind='empty'] { background: color-mix(in srgb, var(--kl-fg) 4%, transparent); }
.kl-code[data-active='true'] { box-shadow: inset 3px 0 var(--kl-warn); }
.kl-dtable[data-mode='split'] td:nth-child(3) { border-right: 1px solid var(--kl-line); }
.kl-hunk td { background: color-mix(in srgb, var(--kl-c1) 12%, transparent); color: var(--kl-muted); padding: 2px 10px; font-size: 12px; }
.kl-gap td { background: color-mix(in srgb, var(--kl-c1) 7%, transparent); padding: 0; }
.kl-gap button { font: inherit; font-size: 12px; color: var(--kl-muted); background: none; border: 0; width: 100%; text-align: left; padding: 4px 12px; cursor: pointer; }
.kl-gap button:hover { color: var(--kl-fg); background: color-mix(in srgb, var(--kl-c1) 14%, transparent); }
.kl-comment-row td { padding: 6px 12px 8px 60px; background: var(--kl-surface); }
.kl-comment { border: 1px solid var(--kl-line); border-radius: 8px; padding: 8px 10px; background: var(--kl-bg); font-size: 13px; max-width: 560px; }

/* FlowCanvas */
.kl-legendrow { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 12px; color: var(--kl-muted); }
.kl-ldot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-left: 6px; background: var(--kl-line); }
.kl-legendrow .kl-ldot { margin: 0 4px 0 0; }
.kl-ldot[data-s='done'] { background: var(--kl-good); }
.kl-ldot[data-s='active'] { background: var(--kl-c1); }
.kl-ldot[data-s='blocked'] { background: var(--kl-bad); }
.kl-canvas { position: relative; margin-top: 10px; border: 1px solid var(--kl-line); border-radius: 10px; overflow: hidden; background: var(--kl-surface); cursor: grab; touch-action: none; user-select: none; }
.kl-canvas:active { cursor: grabbing; }
.kl-canvas:focus-visible { outline: 2px solid var(--kl-accent); outline-offset: 2px; }
.kl-dots { position: absolute; inset: 0; pointer-events: none; }
.kl-dot-fill { fill: color-mix(in srgb, var(--kl-fg) 20%, transparent); }
.kl-world { position: absolute; left: 0; top: 0; transform-origin: 0 0; will-change: transform; }
.kl-laneband { position: absolute; border-block: 1px solid var(--kl-line); background: color-mix(in srgb, var(--kl-fg) 3%, transparent); pointer-events: none; }
.kl-laneband[data-odd='1'] { background: transparent; }
.kl-laneband span { position: absolute; left: 8px; top: 5px; font-size: 12px; font-weight: 500; color: var(--kl-muted); }
.kl-edges { position: absolute; left: 0; pointer-events: none; }
.kl-edges g[data-on='false'] { opacity: 0.14; }
.kl-edges .kl-flow-edge { stroke-width: 1.6; }
.kl-edges g[data-animated='true'] .kl-flow-edge { stroke: var(--kl-c1); stroke-dasharray: 6 5; animation: kl-dash 0.9s linear infinite; }
@keyframes kl-dash { to { stroke-dashoffset: -11; } }
@media (prefers-reduced-motion: reduce) { .kl-edges g[data-animated='true'] .kl-flow-edge { animation: none; } }
.kl-edge-pill { fill: var(--kl-bg); stroke: var(--kl-line); }
.kl-fnode { position: absolute; font: inherit; color: inherit; text-align: left; background: var(--kl-bg); border: 1.5px solid var(--kl-line); border-radius: 10px; padding: 7px 12px; display: grid; align-content: center; gap: 1px; cursor: pointer; transition: opacity 0.15s; }
.kl-fnode:hover { border-color: var(--kl-muted); }
.kl-fnode:focus-visible { outline: 2px solid var(--kl-accent); outline-offset: 2px; }
.kl-fnode[data-kind='gate'] { border-style: dashed; border-color: var(--kl-warn); border-radius: 22px; }
.kl-fnode[data-kind='end'] { border-radius: 29px; }
.kl-fnode[data-kind='start'] { border-radius: 29px; border-color: var(--kl-c3); }
.kl-fnode[data-status='done'] { border-color: var(--kl-good); }
.kl-fnode[data-status='active'] { border-color: var(--kl-c1); background: color-mix(in srgb, var(--kl-c1) 8%, var(--kl-bg)); }
.kl-fnode[data-status='blocked'] { border-color: var(--kl-bad); background: color-mix(in srgb, var(--kl-bad) 7%, var(--kl-bg)); }
.kl-fnode[data-selected='true'] { outline: 2px solid var(--kl-accent); outline-offset: 2px; }
.kl-fnode[data-dim='true'] { opacity: 0.35; }
.kl-fkind { font-size: 11.5px; color: var(--kl-muted); display: flex; align-items: center; justify-content: space-between; }
.kl-flabel { font-weight: 600; font-size: 13.5px; line-height: 1.25; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.kl-handle { position: absolute; top: 50%; width: 9px; height: 9px; margin-top: -4.5px; border-radius: 50%; background: var(--kl-bg); border: 1.5px solid var(--kl-muted); }
.kl-handle[data-side='l'] { left: -5px; } .kl-handle[data-side='r'] { right: -5px; }
.kl-fctl { position: absolute; left: 10px; bottom: 10px; display: flex; border: 1px solid var(--kl-line); border-radius: 8px; overflow: hidden; background: var(--kl-bg); }
.kl-fctl button { font: inherit; width: 30px; height: 30px; background: none; border: 0; border-left: 1px solid var(--kl-line); color: inherit; cursor: pointer; }
.kl-fctl button:first-child { border-left: 0; }
.kl-fctl button:hover, .kl-fctl button[aria-pressed='true'] { background: var(--kl-surface); }
.kl-minimap { position: absolute; right: 10px; bottom: 10px; background: var(--kl-bg); border: 1px solid var(--kl-line); border-radius: 8px; cursor: pointer; }
.kl-mm-node { fill: var(--kl-muted); opacity: 0.5; }
.kl-mm-node[data-status='done'] { fill: var(--kl-good); opacity: 0.8; } .kl-mm-node[data-status='active'] { fill: var(--kl-c1); opacity: 0.9; } .kl-mm-node[data-status='blocked'] { fill: var(--kl-bad); opacity: 0.9; }
.kl-mm-view { fill: color-mix(in srgb, var(--kl-accent) 10%, transparent); stroke: var(--kl-accent); stroke-width: 1.2; }
.kl-fdetail { display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 16px; }
.kl-fdetail .kl-linkbtn { display: block; text-align: left; margin-top: 2px; }
@media (max-width: 640px) { .kl-fdetail { grid-template-columns: 1fr; } }

/* DataGrid */
.kl-dg { position: relative; overflow: auto; border: 1px solid var(--kl-line); border-radius: 10px; background: var(--kl-bg); margin-top: 10px; outline-offset: 2px; }
.kl-dg:focus-visible { outline: 2px solid var(--kl-accent); }
.kl-ghead { position: sticky; top: 0; z-index: 4; display: grid; background: var(--kl-surface); border-bottom: 1px solid var(--kl-line); font-size: 12.5px; }
.kl-gfilters { z-index: 3; }
.kl-gcell { display: flex; align-items: center; padding: 0 10px; min-width: 0; overflow: hidden; background: inherit; }
.kl-gcell[data-align='right'] { justify-content: flex-end; text-align: right; }
.kl-ghcell { position: relative; font-weight: 600; color: var(--kl-muted); }
.kl-ghcell .kl-sortbtn { font: inherit; font-weight: 600; color: inherit; }
.kl-ghcell .kl-sortbtn:hover { color: var(--kl-fg); }
.kl-ghcell sup { font-size: 11px; margin-left: 1px; }
.kl-resize { position: absolute; right: 0; top: 6px; bottom: 6px; width: 7px; cursor: col-resize; border-right: 1px solid var(--kl-line); touch-action: none; }
.kl-resize:hover { border-right: 2px solid var(--kl-accent); }
.kl-gcheck { justify-content: center; padding: 0; background: var(--kl-surface); }
.kl-gbody { position: relative; }
.kl-grow { position: absolute; left: 0; display: grid; align-items: stretch; border-bottom: 1px solid color-mix(in srgb, var(--kl-line) 60%, transparent); background: var(--kl-bg); font-size: 13px; }
.kl-grow .kl-gcheck { background: var(--kl-bg); }
.kl-grow:hover, .kl-grow:hover .kl-gcheck { background: var(--kl-surface); }
.kl-grow[data-selected='true'], .kl-grow[data-selected='true'] .kl-gcheck { background: color-mix(in srgb, var(--kl-accent) 11%, var(--kl-bg)); }
.kl-grow[data-active='true'] { box-shadow: inset 2px 0 var(--kl-accent); }
.kl-dg:not(:focus-visible) .kl-grow[data-active='true'] { box-shadow: none; }
.kl-gfilters .kl-gcell { background: var(--kl-surface); }
.kl-finput { width: 100%; padding: 2px 6px; min-width: 0; font-size: 12px; }
.kl-finput[data-bad='true'] { border-color: var(--kl-bad); }
.kl-pctcell { display: inline-flex; align-items: center; gap: 8px; width: 100%; justify-content: flex-end; }
.kl-pctbar { width: 54px; height: 6px; border-radius: 3px; background: var(--kl-line); overflow: hidden; }
.kl-pctbar > span { display: block; height: 100%; background: var(--kl-c3); }
.kl-spark polyline { stroke: var(--kl-c1); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }
.kl-spark circle { fill: var(--kl-c1); }
.kl-selbar { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 6px 12px; border-radius: 8px; background: color-mix(in srgb, var(--kl-accent) 10%, var(--kl-bg)); font-size: 13px; }
.kl-gempty { position: sticky; left: 24px; padding: 40px 0; display: grid; justify-items: start; gap: 6px; }
.kl-gfoot { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 18px; margin-top: 8px; font-size: 12.5px; }

/* Charts */
.kl-spc, .kl-sankey { position: relative; margin-top: 8px; }
.kl-spc svg, .kl-sankey svg { display: block; overflow: visible; }
.kl-axis-line { stroke: color-mix(in srgb, var(--kl-fg) 9%, transparent); }
.kl-axis-text { fill: var(--kl-muted); font: 11px system-ui, sans-serif; }
.kl-zone3 { fill: color-mix(in srgb, var(--kl-c1) 6%, transparent); }
.kl-zone2 { fill: color-mix(in srgb, var(--kl-c1) 7%, transparent); }
.kl-zone1 { fill: color-mix(in srgb, var(--kl-c3) 11%, transparent); }
.kl-limit { stroke: var(--kl-bad); stroke-width: 1.2; stroke-dasharray: 4 3; opacity: 0.8; }
.kl-center { stroke: var(--kl-fg); stroke-width: 1.3; opacity: 0.55; }
.kl-baseline { fill: color-mix(in srgb, var(--kl-fg) 5%, transparent); }
.kl-marker { stroke: var(--kl-muted); stroke-width: 1; stroke-dasharray: 2 3; }
.kl-series { stroke: var(--kl-c1); stroke-width: 1.6; stroke-linejoin: round; }
.kl-pt { fill: var(--kl-bg); stroke: var(--kl-c1); stroke-width: 1.6; }
.kl-pt[data-signal='true'] { fill: var(--kl-bad); stroke: var(--kl-bg); stroke-width: 1.5; }
.kl-pt[data-hover='true'] { stroke-width: 3; }
.kl-rule { fill: var(--kl-bad); font: 700 11px system-ui, sans-serif; }
.kl-cross { stroke: var(--kl-fg); stroke-width: 1; opacity: 0.3; }
.kl-slink { opacity: 0.32; transition: opacity 0.12s; mix-blend-mode: normal; }
.kl-slink[data-active='false'] { opacity: 0.06; }
.kl-slink:hover { opacity: 0.6; }
.kl-snode { opacity: 0.9; }
.kl-slabel { fill: var(--kl-fg); font: 600 12.5px system-ui, sans-serif; }
.kl g[data-leak='true'] .kl-slabel { fill: var(--kl-bad); }

/* ApprovalQueue */
.kl-queue-body { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 16px; margin-top: 12px; align-items: start; outline-offset: 4px; border-radius: 10px; }
.kl-queue-body:focus-visible { outline: 2px solid var(--kl-accent); }
.kl-qlist { display: grid; gap: 4px; }
.kl-qitem { display: grid; grid-template-columns: 8px minmax(0, 1fr); gap: 10px; align-items: stretch; padding: 8px 10px; border: 1px solid var(--kl-line); border-radius: 10px; cursor: pointer; background: var(--kl-bg); }
.kl-qitem:hover { background: var(--kl-surface); }
.kl-qitem[data-selected='true'] { border-color: var(--kl-accent); outline: 1px solid var(--kl-accent); }
.kl-qmain { min-width: 0; display: grid; justify-items: start; }
.kl-qtitle { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; line-height: 1.3; }
.kl-risk { width: 8px; min-height: 30px; border-radius: 4px; background: var(--kl-good); }
.kl-risk[data-risk='medium'] { background: var(--kl-warn); } .kl-risk[data-risk='high'] { background: var(--kl-bad); }
.kl-qdetail { border: 1px solid var(--kl-line); border-radius: 10px; padding: 14px; min-width: 0; }
.kl-statusline { margin: 4px 0 10px; padding: 6px 10px; border-radius: 8px; background: var(--kl-surface); font-size: 13px; }
.kl-statusline[data-status='stale'], .kl-statusline[data-status='expired'], .kl-statusline[data-status='rejected'] { background: color-mix(in srgb, var(--kl-bad) 10%, var(--kl-bg)); color: var(--kl-bad); }
.kl-statusline[data-status='approved'] { background: color-mix(in srgb, var(--kl-good) 10%, var(--kl-bg)); color: var(--kl-good); }
.kl-qgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; }
.kl-qhead { font-size: 12.5px; font-weight: 500; color: var(--kl-muted); margin-bottom: 4px; }
.kl-evidence { display: grid; gap: 4px; font-size: 13px; }
.kl-evidence li { display: grid; grid-template-columns: 18px 1fr; gap: 4px; }
.kl-evidence li[data-ok='true'] > span:first-child { color: var(--kl-good); } .kl-evidence li[data-ok='false'] > span:first-child { color: var(--kl-bad); font-weight: 700; }
.kl-dlog { display: grid; gap: 3px; font-size: 13px; }
.kl-dlog li[data-ignored='true'] { opacity: 0.7; } .kl-ignored { color: var(--kl-bad); }
.kl-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.kl-btn { font: inherit; font-weight: 600; font-size: 13px; padding: 8px 14px; border-radius: 8px; border: 1px solid var(--kl-line); background: var(--kl-bg); color: var(--kl-fg); cursor: pointer; }
.kl-btn:hover:not(:disabled) { background: var(--kl-surface); }
.kl-btn[data-kind='approve'] { background: var(--kl-accent); color: var(--kl-bg); border-color: var(--kl-accent); }
.kl-btn[data-kind='reject'] { color: var(--kl-bad); border-color: currentColor; }
.kl-btn:disabled { opacity: 0.42; cursor: not-allowed; }
.kl-btn:focus-visible { outline: 2px solid var(--kl-accent); outline-offset: 2px; }
@media (max-width: 760px) { .kl-queue-body { grid-template-columns: 1fr; } }

/* DeadlineGantt */
.kl-gantt { position: relative; margin-top: 8px; overflow-x: auto; }
.kl-gantt svg { display: block; }
.kl-gbar { fill: var(--kl-c1); }
.kl-gbar[data-state='met'] { fill: var(--kl-good); } .kl-gbar[data-state='late'], .kl-gbar[data-state='overdue'] { fill: var(--kl-c1); } .kl-gbar[data-state='remedied'] { fill: var(--kl-warn); }
.kl-gover { fill: url(#klx-hatch); stroke: var(--kl-bad); stroke-width: 1; }
.kl-hatch-bg { fill: color-mix(in srgb, var(--kl-bad) 14%, var(--kl-bg)); } .kl-hatch-line { stroke: var(--kl-bad); stroke-width: 2; }
.kl-diamond { fill: var(--kl-bg); stroke: var(--kl-fg); stroke-width: 1.6; }
.kl-diamond[data-state='overdue'], .kl-diamond[data-state='late'] { stroke: var(--kl-bad); fill: var(--kl-bad); }
.kl-diamond[data-state='met'] { stroke: var(--kl-good); }
.kl-now { stroke: var(--kl-c1); stroke-width: 1.4; stroke-dasharray: 3 3; }
.kl-now-text { fill: var(--kl-c1); font: 700 11px system-ui, sans-serif; }

/* ActivityHeatmap */
.kl-hcell { fill: color-mix(in srgb, var(--kl-fg) 8%, transparent); }
.kl-hcell[data-level='1'], .kl-hcell-sw[data-level='1'] { fill: color-mix(in srgb, var(--kl-c3) 28%, transparent); background: color-mix(in srgb, var(--kl-c3) 28%, transparent); }
.kl-hcell[data-level='2'], .kl-hcell-sw[data-level='2'] { fill: color-mix(in srgb, var(--kl-c3) 50%, transparent); background: color-mix(in srgb, var(--kl-c3) 50%, transparent); }
.kl-hcell[data-level='3'], .kl-hcell-sw[data-level='3'] { fill: color-mix(in srgb, var(--kl-c3) 75%, transparent); background: color-mix(in srgb, var(--kl-c3) 75%, transparent); }
.kl-hcell[data-level='4'], .kl-hcell-sw[data-level='4'] { fill: var(--kl-c3); background: var(--kl-c3); }
.kl-hcell[data-hover='true'] { stroke: var(--kl-fg); stroke-width: 1.5; }
.kl-hbreach { fill: var(--kl-bad); stroke: var(--kl-bg); stroke-width: 1; }
.kl-hlegend { display: flex; align-items: center; gap: 4px; font-size: 12px; color: var(--kl-muted); margin-top: 6px; }
.kl-hcell-sw { display: inline-block; width: 13px; height: 13px; border-radius: 3px; background: color-mix(in srgb, var(--kl-fg) 8%, transparent); }
.kl-hbreach-sw { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--kl-bad); }

.kl-axis-text[data-day='true'] { fill: var(--kl-fg); font-weight: 700; }
.kl-hatch-sw { display: inline-block; width: 16px; height: 10px; border-radius: 2px; border: 1px solid var(--kl-bad); background: repeating-linear-gradient(135deg, var(--kl-bad) 0 2px, transparent 2px 5px); }
.kl-now-sw { display: inline-block; width: 0; height: 12px; border-left: 2px dashed var(--kl-c1); }
.kl-hlegend svg { display: inline-block; }

/* Marks and folds */
.kl-icon { display: inline-block; vertical-align: -2px; flex: none; }
.kl-statement { margin: 4px 0 8px; font-weight: 600; font-size: 15px; line-height: 1.4; }
.kl-remedy { margin: 0 0 6px; }
.kl-fold { margin-top: 6px; font-size: 13px; }
.kl-fold summary { cursor: pointer; color: var(--kl-muted); width: fit-content; }
.kl-fold summary:hover { color: var(--kl-fg); }
.kl-fold p { margin: 6px 0 0; color: var(--kl-muted); }
.kl-verdict svg { width: 18px; height: 18px; }
.kl-cellmark svg { width: 15px; height: 15px; }
.kl-link > span svg { width: 13px; height: 13px; }
.kl-minimap { box-shadow: none; }

/* Figures as type, and key hints on the buttons they belong to */
.kl-figs { display: flex; flex-wrap: wrap; gap: 4px 28px; margin: 0; }
.kl-figs > div { display: flex; flex-direction: column-reverse; }
.kl-figs dd { margin: 0; font-size: 22px; font-weight: 600; line-height: 1.15; }
.kl-figs dt { font-size: 12px; color: var(--kl-muted); }
.kl-figs > div[data-bad='true'] dd { color: var(--kl-bad); }
.kl-bigfig { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; margin: 2px 0 2px; }
.kl-bigfig b { font-size: 26px; font-weight: 600; line-height: 1.1; }
kbd { font: inherit; font-size: 11px; margin-left: 8px; padding: 0 5px; border-radius: 4px; background: color-mix(in srgb, currentColor 14%, transparent); }
.kl-chips { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }

/* Narrow screens: the hash chain stacks instead of scrolling sideways */
@media (max-width: 640px) {
  .kl-chain { flex-direction: column; align-items: stretch; }
  .kl-block { flex: none; }
  .kl-link { flex: none; width: 2px; height: 22px; align-self: center; }
  .kl-link[data-ok='false'] { background: repeating-linear-gradient(180deg, var(--kl-bad) 0 4px, transparent 4px 8px); }
  .kl-link > span { top: 50%; left: 14px; transform: translateY(-50%); }
}
